    if (personalBucket) {
      const newSubs = personalBucket.bills || [];
      // shallow compare to avoid infinite loop
      const same = newSubs.length === subscriptions.length && newSubs.every((s, i) => s === subscriptions[i]);
      if (!same) setSubscriptions(newSubs);
    }
