                      const freq = s.freq || 'monthly';
                      const freqLabel = freq === 'weekly' ? 'Weekly' : freq === 'fortnightly' ? 'Fortnightly' : freq === 'monthly' ? 'Monthly' : freq === 'quarterly' ? 'Quarterly' : freq === 'halfyear' ? '6-Monthly' : 'Annual';
